# Step 2a — Load EMA medicines report (metadata only)
#
# IMPORTANT: This file contains EMEA/H/C/XXXXXX procedure numbers.
# These are NOT the h-numbers used in Union Register URLs.
# We use this file only for drug metadata (status, ATC, INN, MAH, dates).
# The actual Union Register URLs come from Step 2b (scraping the index).
#
# Upload your downloaded Excel from:
# https://www.ema.europa.eu/en/medicines/download-medicine-data
# ─────────────────────────────────────────────────────────────────────────────

import io, re, requests, pandas as pd
from IPython.display import display, HTML

EMA_COL = {
    "name"      : "Name of medicine",
    "proc"      : "EMA product number",   # EMEA/H/C/XXXXXX — NOT the h-number
    "category"  : "Category",
    "status"    : "Medicine status",
    "inn"       : "International non-proprietary name (INN) / common name",
    "substance" : "Active substance",
    "atc"       : "ATC code (human)",
    "mah"       : "Marketing authorisation developer / applicant / holder",
    "ma_date"   : "Marketing authorisation date",
    "decision"  : "European Commission decision date",
    "ta"        : "Therapeutic area (MeSH)",
    "orphan"    : "Orphan medicine",
    "biosimilar": "Biosimilar",
    "generic"   : "Generic",
    "indication": "Therapeutic indication",
    "ema_url"   : "Medicine URL",
}

def parse_ema_excel(file_bytes):
    df_raw = pd.read_excel(io.BytesIO(file_bytes), header=8, sheet_name=0)
    real_cols = [c for c in df_raw.columns
                 if c and "Unnamed" not in str(c) and str(c).strip()]
    df = df_raw[real_cols].copy()
    if EMA_COL["category"] in df.columns:
        df = df[df[EMA_COL["category"]] == "Human"].copy()
    rename = {v: k for k, v in EMA_COL.items() if v in df.columns}
    df = df.rename(columns=rename)
    df["drug_name"] = df["name"].fillna("").astype(str).str.strip()
    # Normalise join key: lowercase, strip, collapse spaces
    df["_join_key"] = df["drug_name"].str.lower().str.strip().str.replace(r"\s+", " ", regex=True)
    return df.reset_index(drop=True)

