# ─────────────────────────────────────────────────────────────────────────────
# Step 2b — Load Union Register brand index Excel
#
# Source: https://ec.europa.eu/health/documents/community-register/html/reg_index_brand.htm
#         → click "Download as Excel"
#
# Structure (header on row 2, 0-indexed):
#   Col 0 (unnamed)  : CH = Centrally authorised Human
#                      CV = Centrally authorised Veterinary
#                      NH = Nationally authorised Human
#                      NV = Nationally authorised Veterinary
#   "Brand name"     : medicine name
#   "EU number"      : EU/1/YY/NNN  (human CAP)  or  EU/2/...  (vet)  or  -
#   "Reference name" : canonical name (referrals)
#
# We filter CH rows and extract NNN from EU/1/YY/NNN → h-number.
# ─────────────────────────────────────────────────────────────────────────────

import io, re
import requests
import pandas as pd

BRAND_INDEX_URL = (
    "https://ec.europa.eu/health/documents/community-register/"
    "html/reg_index_brand.xlsx"
)
EU_MA_RE = re.compile(r'/1/\d{2}/(\d+)')   # EU/1/YY/NNN → group 1 = NNN

def parse_brand_index(file_bytes: bytes) -> pd.DataFrame:
    """
    Parse the Union Register brand index Excel.
    Returns a DataFrame with columns:
      brand_name, eu_number, product_number, url, category
    """
    df = pd.read_excel(io.BytesIO(file_bytes), header=2)
    df.columns = ["category", "brand_name", "eu_number", "reference_name"]
    df = df.dropna(subset=["brand_name"])
    df["brand_name"] = df["brand_name"].astype(str).str.strip()
    df["eu_number"]  = df["eu_number"].astype(str).str.strip()
    df["category"]   = df["category"].astype(str).str.strip()

    # Human CAP only: category == "CH" and EU number matches EU/1/...
    ch = df[df["category"] == "CH"].copy()
    ch["product_number"] = ch["eu_number"].apply(
        lambda x: int(m.group(1)) if (m := EU_MA_RE.search(str(x))) else None
    )
    ch = ch.dropna(subset=["product_number"])
    ch["product_number"] = ch["product_number"].astype(int)
    ch["url"] = ch["product_number"].apply(
        lambda n: f"https://ec.europa.eu/health/documents/community-register/html/h{n}.htm"
    )
    # Normalised join key for merging with EMA metadata
    ch["_key"] = ch["brand_name"].str.lower().str.strip()
    return ch[["brand_name","eu_number","product_number","url","category","_key"]].reset_index(drop=True)

