    r = requests.get(BRAND_INDEX_URL, timeout=30,
                     headers={"User-Agent": "Mozilla/5.0"})
    r.raise_for_status()
    df_brand_index = parse_brand_index(r.content)
    print(f"\u2705  Downloaded: {len(df_brand_index):,} human CAP products")

