# ─────────────────────────────────────────────────────────────────────────────
# Step 3 — Build master table
#
# df_brand_index : brand name + EU number + h-number + URL  (Union Register Excel)
# df_ema_meta    : status, ATC, INN, MAH, dates  (EMA medicines report Excel)
#
# Join key: brand name normalised to lowercase with parentheticals stripped.
# e.g. "Abasaglar (previously Abasria)" → "abasaglar"  matches  "Abasaglar"
# ─────────────────────────────────────────────────────────────────────────────

import re

def norm_key(s: str) -> str:
    """Lowercase, strip parentheticals, collapse whitespace."""
    s = re.sub(r'\s*\(.*?\)', '', str(s))   # drop "(previously ...)" etc.
    return s.lower().strip()

# Both sides use the same normalisation
df_brand_index["_key"] = df_brand_index["brand_name"].apply(norm_key)
df_ema_meta["_key"]    = df_ema_meta["drug_name"].apply(norm_key)

meta_keep = ["_key","proc","status","inn","substance","atc","mah",
             "ma_date","decision","ta","orphan","biosimilar","generic",
             "indication","ema_url"]
meta_keep = [c for c in meta_keep if c in df_ema_meta.columns]

df_all = df_brand_index.merge(
    df_ema_meta[meta_keep].drop_duplicates("_key"),
    on="_key", how="left"
)

def cap_type(row):
    s = str(row.get("status","")).lower()
    if "authoris" in s:                                        return "CAP Active"
    if any(x in s for x in ("withdrawn","lapsed","expired","revoked")): return "CAP Inactive"
    if "refused" in s:                                         return "CAP Refused"
    return "CAP"

df_all["authorisation_type"] = df_all.apply(cap_type, axis=1)

for col in df_all.select_dtypes(include="object").columns:
    df_all[col] = df_all[col].fillna("").astype(str).replace("nan","").str.strip()

df_all = df_all.sort_values("product_number").reset_index(drop=True)

